     1	<!DOCTYPE html>
     2	<html lang="en">
     3	<head>
     4	<meta charset="utf-8">
     5	<meta name="viewport" content="width=device-width, initial-scale=1">
     6	<title>Room bookings</title>
     7	<style>
     8	  :root {
     9	    --ink: #1d2433;
    10	    --muted: #5b6475;
    11	    --line: #d8dde6;
    12	    --paper: #f6f7f9;
    13	    --accent: #2f5bd3;
    14	    --danger: #b3261e;
    15	  }
    16	  * { box-sizing: border-box; }
    17	  body {
    18	    margin: 0;
    19	    padding: 2rem 1rem 4rem;
    20	    font: 16px/1.5 system-ui, sans-serif;
    21	    color: var(--ink);
    22	    background: var(--paper);
    23	  }
    24	  main { max-width: 42rem; margin: 0 auto; }
    25	  h1 { margin: 0 0 1.5rem; font-size: 1.75rem; letter-spacing: -0.01em; }
    26	  h2 { margin: 2rem 0 0.75rem; font-size: 1.125rem; }
    27	  form, .filter {
    28	    display: grid;
    29	    gap: 0.75rem 1rem;
    30	    padding: 1.25rem;
    31	    background: #fff;
    32	    border: 1px solid var(--line);
    33	    border-radius: 0.5rem;
    34	  }
    35	  form { grid-template-columns: repeat(auto-fill, minmax(9rem, 1fr)); }
    36	  .filter { grid-template-columns: 1fr auto; align-items: end; }
    37	  .field { display: grid; gap: 0.25rem; }
    38	  .field.wide { grid-column: 1 / -1; }
    39	  label { font-size: 0.875rem; font-weight: 600; color: var(--muted); }
    40	  input, select, button { font: inherit; }
    41	  input, select {
    42	    width: 100%;
    43	    padding: 0.4rem 0.5rem;
    44	    border: 1px solid var(--line);
    45	    border-radius: 0.375rem;
    46	    background: #fff;
    47	    color: var(--ink);
    48	  }
    49	  button {
    50	    padding: 0.45rem 1rem;
    51	    border: 1px solid var(--accent);
    52	    border-radius: 0.375rem;
    53	    background: var(--accent);
    54	    color: #fff;
    55	    cursor: pointer;
    56	  }
    57	  button[type="button"] { background: #fff; color: var(--accent); }
    58	  button:disabled { opacity: 0.55; cursor: progress; }
    59	  :focus-visible { outline: 3px solid var(--accent); outline-offset: 2px; }
    60	  #book { align-self: end; }
    61	  #error { min-height: 1.5em; margin: 1rem 0 0; color: var(--danger); font-weight: 600; }
    62	  #booking-list { list-style: none; margin: 0; padding: 0; }
    63	  #booking-list li {
    64	    display: flex;
    65	    justify-content: space-between;
    66	    align-items: center;
    67	    gap: 1rem;
    68	    padding: 0.6rem 0.25rem;
    69	    border-bottom: 1px solid var(--line);
    70	    overflow-wrap: anywhere;
    71	  }
    72	</style>
    73	</head>
    74	<body>
    75	<main>
    76	  <h1>Room bookings</h1>
    77	  <form id="booking-form" novalidate>
    78	    <div class="field">
    79	      <label for="room">Room</label>
    80	      <select id="room" name="room"></select>
    81	    </div>
    82	    <div class="field wide">
    83	      <label for="title">Title</label>
    84	      <input type="text" id="title" name="title">
    85	    </div>
    86	    <div class="field">
    87	      <label for="date">Date</label>
    88	      <input type="date" id="date" name="date">
    89	    </div>
    90	    <div class="field">
    91	      <label for="start">Start</label>
    92	      <input type="time" id="start" name="start">
    93	    </div>
    94	    <div class="field">
    95	      <label for="end">End</label>
    96	      <input type="time" id="end" name="end">
    97	    </div>
    98	    <button type="submit" id="book">Book</button>
    99	  </form>
   100	  <p id="error" role="alert"></p>
   101	  <h2>Bookings</h2>
   102	  <div class="filter">
   103	    <div class="field">
   104	      <label for="filter-date">Show date</label>
   105	      <input type="date" id="filter-date">
   106	    </div>
   107	    <button type="button" id="show-all">Show all</button>
   108	  </div>
   109	  <ul id="booking-list"></ul>
   110	</main>
   111	<script src="/app.js"></script>
   112	</body>
   113	</html>
     1	'use strict';
     2	
     3	(function main() {
     4	  const NO_REPLY = 'Could not reach the server.';
     5	  const FALLBACK_ERROR = 'Request failed.';
     6	
     7	  const form = document.getElementById('booking-form');
     8	  const roomSelect = document.getElementById('room');
     9	  const titleInput = document.getElementById('title');
    10	  const dateInput = document.getElementById('date');
    11	  const startInput = document.getElementById('start');
    12	  const endInput = document.getElementById('end');
    13	  const bookButton = document.getElementById('book');
    14	  const filterInput = document.getElementById('filter-date');
    15	  const showAllButton = document.getElementById('show-all');
    16	  const list = document.getElementById('booking-list');
    17	  const errorBox = document.getElementById('error');
    18	
    19	  let latestListFetch = 0;
    20	
    21	  function isPlainObject(value) {
    22	    return value !== null && typeof value === 'object' && !Array.isArray(value);
    23	  }
    24	
    25	  function errorMessage(body) {
    26	    return isPlainObject(body) && typeof body.error === 'string' ? body.error : FALLBACK_ERROR;
    27	  }
    28	
    29	  function showError(message) {
    30	    errorBox.textContent = message;
    31	  }
    32	
    33	  // Resolves to { reached: false } when there is no usable reply,
    34	  // otherwise to { reached: true, ok, body }. A 204 body is never read.
    35	  async function request(url, options, successStatus) {
    36	    let response;
    37	    try {
    38	      response = await fetch(url, options);
    39	    } catch (err) {
    40	      return { reached: false, cause: err };
    41	    }
    42	    if (response.status === 204) {
    43	      return { reached: true, ok: successStatus === 204, body: null };
    44	    }
    45	    try {
    46	      const body = await response.json();
    47	      return { reached: true, ok: response.status === successStatus, body };
    48	    } catch (err) {
    49	      return { reached: false, cause: err };
    50	    }
    51	  }
    52	
    53	  function bookingText(booking) {
    54	    return `${booking.date} ${booking.start}-${booking.end} ${booking.room}: ${booking.title}`;
    55	  }
    56	
    57	  function renderBooking(booking) {
    58	    const item = document.createElement('li');
    59	    const cancel = document.createElement('button');
    60	    cancel.type = 'button';
    61	    cancel.textContent = 'Cancel';
    62	    cancel.addEventListener('click', () => cancelBooking(booking.id, cancel));
    63	    item.append(bookingText(booking), cancel);
    64	    return item;
    65	  }
    66	
    67	  function renderList(bookings) {
    68	    if (bookings.length === 0) {
    69	      const empty = document.createElement('li');
    70	      empty.append('No bookings.');
    71	      list.replaceChildren(empty);
    72	      return;
    73	    }
    74	    list.replaceChildren(...bookings.map(renderBooking));
    75	  }
    76	
    77	  function listUrl() {
    78	    const date = filterInput.value;
    79	    return date === '' ? '/api/bookings' : `/api/bookings?date=${date}`;
    80	  }
    81	
    82	  async function loadList() {
    83	    latestListFetch += 1;
    84	    const ticket = latestListFetch;
    85	    const result = await request(listUrl(), undefined, 200);
    86	    if (ticket !== latestListFetch) {
    87	      return;
    88	    }
    89	    if (!result.reached) {
    90	      showError(NO_REPLY);
    91	    } else if (!result.ok) {
    92	      showError(errorMessage(result.body));
    93	    } else if (isPlainObject(result.body) && Array.isArray(result.body.bookings)) {
    94	      renderList(result.body.bookings);
    95	    } else {
    96	      showError(FALLBACK_ERROR);
    97	    }
    98	  }
    99	
   100	  async function loadRooms() {
   101	    const result = await request('/api/rooms', undefined, 200);
   102	    if (!result.reached) {
   103	      showError(NO_REPLY);
   104	    } else if (!result.ok) {
   105	      showError(errorMessage(result.body));
   106	    } else if (isPlainObject(result.body) && Array.isArray(result.body.rooms)) {
   107	      const options = result.body.rooms.map((name) => {
   108	        const option = document.createElement('option');
   109	        option.value = name;
   110	        option.textContent = name;
   111	        return option;
   112	      });
   113	      roomSelect.replaceChildren(...options);
   114	    } else {
   115	      showError(FALLBACK_ERROR);
   116	    }
   117	  }
   118	
   119	  async function cancelBooking(id, button) {
   120	    button.disabled = true;
   121	    const result = await request(`/api/bookings/${id}`, { method: 'DELETE' }, 204);
   122	    button.disabled = false;
   123	    if (!result.reached) {
   124	      showError(NO_REPLY);
   125	      return;
   126	    }
   127	    showError(result.ok ? '' : errorMessage(result.body));
   128	    loadList();
   129	  }
   130	
   131	  async function submitBooking(event) {
   132	    event.preventDefault();
   133	    if (bookButton.disabled) {
   134	      return;
   135	    }
   136	    bookButton.disabled = true;
   137	    const payload = {
   138	      room: roomSelect.value,
   139	      title: titleInput.value,
   140	      date: dateInput.value,
   141	      start: startInput.value,
   142	      end: endInput.value,
   143	    };
   144	    const result = await request('/api/bookings', {
   145	      method: 'POST',
   146	      headers: { 'Content-Type': 'application/json' },
   147	      body: JSON.stringify(payload),
   148	    }, 201);
   149	    bookButton.disabled = false;
   150	    if (!result.reached) {
   151	      showError(NO_REPLY);
   152	    } else if (!result.ok) {
   153	      showError(errorMessage(result.body));
   154	    } else {
   155	      titleInput.value = '';
   156	      showError('');
   157	      loadList();
   158	    }
   159	  }
   160	
   161	  function showAll() {
   162	    filterInput.value = '';
   163	    loadList();
   164	  }
   165	
   166	  form.addEventListener('submit', submitBooking);
   167	  filterInput.addEventListener('change', loadList);
   168	  showAllButton.addEventListener('click', showAll);
   169	
   170	  loadRooms();
   171	  loadList();
   172	}());
